# filename: test_quantitative.py | Code Generated by Sidekick is for learning and experimentation purposes only.
from agents.quantitative import run


def main():
    question = input("Ask a data question: ").strip()

    if not question:
        print("Please enter a question.")
        return

    try:
        result = run(question)

        print("\nANSWER:")
        print(result.get("answer", ""))

        print("\nSQL:")
        print(result.get("sql", ""))

        print("\nCOLUMNS:")
        print(result.get("columns", []))

        print("\nROWS:")
        for row in result.get("rows", []):
            print(row)

        print(f"\nValidation: {result.get('validation', 'UNKNOWN')}")
        print(f"Input tokens: {result.get('input_tokens', 'N/A')}")
        print(f"Output tokens: {result.get('output_tokens', 'N/A')}")

    except Exception as error:
        print(f"\nTest failed: {error}")


if __name__ == "__main__":
    main()

